AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS API Gateway container

Container_Boundary(aws_api_gateway, "AWS API Gateway") {
    Component(External_Ingress_Manager, "External Ingress Manager", "AWS API Gateway", "Manages external ingress, rate-limiting, and payload size restriction to protect downstream services within budget.")
}

System_Ext(Payment_Gateway, "Payment Gateway", "Sends payment authorization requests")
Container(Tokenization_Proxy_Container, "Tokenization Proxy Container", "Container", "Proxies and tokenizes payment data")

Rel(Payment_Gateway, External_Ingress_Manager, "Sends payment authorization requests", "HTTPS/TLS 1.3")
Rel(External_Ingress_Manager, Tokenization_Proxy_Container, "Forwards payment data", "gRPC/Protobuf")

@enduml

Modular Monolith Core Scoring Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Modular Monolith Core Scoring Engine container

Container_Boundary(core_scoring_engine, "Modular Monolith Core Scoring Engine") {
    Component(fail_fast_validation_pipeline, "Fail-Fast Validation Pipeline", "Java", "Performs immediate validation checks on incoming payment data to quickly reject malformed requests.")
    Component(rule_evaluation_module, "Rule-Evaluation Module", "Java, Strategy Pattern, Atomic References", "Evaluates transactions against fraud rules with zero-downtime hot-swapping capability in memory.")
    Component(ml_scoring_module, "ML-Scoring Module", "Java, Atomic References", "Scores transactions using machine learning models with zero-downtime hot-swapping capability in memory.")
}

Rel(fail_fast_validation_pipeline, rule_evaluation_module, "Passes validated payment data for rule evaluation")
Rel(rule_evaluation_module, ml_scoring_module, "Passes data for ML-based fraud scoring")
@enduml

Amazon SQS Message Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon SQS Message Bus container

System_Ext(Modular_Monolith_Core_Scoring_Engine, "Modular Monolith Core Scoring Engine", "Core scoring engine container")
System_Ext(Case_Management_Service, "Case Management Service", "Case management service container")

Container_Boundary(Amazon_SQS_Message_Bus, "Amazon SQS Message Bus") {
    Component(Review_Case_Queue, "Review Case Queue", "Amazon SQS", "Provides transient decoupling, load-leveling, and asynchronous routing of review cases using SQS Long Polling and the S3 Claims Check pattern.")
}

Rel(Modular_Monolith_Core_Scoring_Engine, Review_Case_Queue, "Asynchronously routes review cases using Amazon SQS API", "Amazon SQS API")
Rel(Review_Case_Queue, Case_Management_Service, "Triggers asynchronous case processing via SQS Long Polling", "SQS Long Polling")

@enduml

AWS S3 Object Lock.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_s3_object_lock, "AWS S3 Object Lock") {
    Component(Object_Lock_Manager, "Object Lock Manager", "AWS S3 Native Service", "Enforces immutable, tamper-evident 7-year audit retention for PCI-DSS compliance.")
    Component(Lifecycle_Transition_Engine, "Lifecycle Transition Engine", "S3 Lifecycle Policies", "Transitions older audit logs to AWS S3 Glacier to reduce storage costs.")
}

Rel(Object_Lock_Manager, Lifecycle_Transition_Engine, "Triggers automated lifecycle movement", "S3 Lifecycle")

@enduml

AWS S3 Glacier.diagram:
